window.VD=window.VD||{};window.VD["vw/touareg-7p"]={"touareg-7p-activate-daytime-running-lights-drl-on-rns":"<p><strong>Purpose</strong>: To activate the daytime running lights (DRL) on the display (RNS 810/850).   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“<strong>Long Coding Helper</strong>”.</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 3 </strong>:</p>\n<p>Bit<strong> 0 </strong>: Check<em> <strong>“Daytime Running Lights Adjustable via Car Menu”.</strong> </em> </p>","touareg-7p-activate-dvd-playback-while-driving-vim":"<p><strong>Purpose</strong>: Allows you to remove the RNS 850 protection and continue watching a DVD or video while driving (Video in Motion).   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Step 1: Retrieving the RNS 850 serial number</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Advanced Ident -1A</strong>”.</p>\n<p>Retrieve serial number (if more than one, use the <strong>first</strong> one!)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a1_8x_mmi_plus_5f_seriennummer-PNG-12291981.webp\"/></figure>\n<p><strong>Step 2: Calculating the security code</strong></p>\n<p>Enter the serial number previously retrieved from the website (your choice, subject to availability):  </p>\n<p>–&gt; <a href=\"https://www.audienthusiasts.com/Articles_VIM.html\" rel=\"noopener\" target=\"_blank\">AUDIENTHUSIATS VIM</a></p>\n<p>–&gt; <a href=\"https://www.bestcarmods.com/vim/\" rel=\"noopener\" target=\"_blank\">BESTCARMODS VIM</a></p>\n<p>The site will display your security code.<br/><em>An alternative security code is also generated.</em></p>\n<p><strong>Step 3: Enter security code</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Secure access -16</strong>”.</p>\n<p>Enter security code <br/><em>(Use alternative security code if first code does not work)</em></p>\n<p><strong>Step 4: Removing the protection</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation -10</strong>”.</p>\n<p><strong>5 – </strong>Select Channel <strong>48</strong> </p>\n<p><em>Set value to <strong>255</strong></em></p>\n<p><strong>Step 5: Restarting the RNS 850</strong></p>\n<p>Simultaneously press PHONE (1) + CLIMATE (2) + Central knob (3) + NAV (4) + TRAFFIC (5)</p>","touareg-7p-activate-hidden-menu-rns-850":"<p><strong>Purpose</strong>: Activates the green hidden menu (green menu, hidden menu, testmode, engineer mode) in the RNS 850.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 6</strong> </em>then set the value to <strong>1</strong></p>\n<p><em>No need to restart the RNS 850.</em></p>\n<p><em>To launch the Hidden Menu press MENU + CAR (for 6s)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/mmi3g-217db9e1.webp\"/></figure>","touareg-7p-activate-off-road-mode":"<p><strong>Purpose</strong>: to activate Offroad mode on the RNS-850.</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/></p>\n<p><strong>To continue, you must first activate the RNS-850’s hidden menu (Green Menu).</strong></p>\n<p><em>To activate the hidden MMI menu (Green Menu), see article: <a href=\"https://www.vag-coding.fr/vw/touareg-7p/touareg-7p-activer-menu-cache-rns-850/\" rel=\"noopener\" target=\"_blank\">RNS 850 – Activate Hidden Menu</a></em></p>\n<p>Press <strong>CAR + SETUP</strong> for 6 sec to bring up the hidden menu.</p>\n<p>diagnostics &gt; settings &gt; Offroad Navigation</p>\n<p>Select [enabled] 1/2</p>\n<p><strong>Restart the RNS-850</strong></p>\n<p>Simultaneously press PHONE + CLIMATE + Central Button Wheel + NAV + TRAFFIC</p>","touareg-7p-activate-stationary-heater":"<p><strong>Purpose</strong>: to activate stationary heating and its management on the RNS 850.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>08 – Auto HVAC</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>01</strong>: </em><br/><em>Bit<strong> 4</strong>: Tick “Auxiliary Heating active”.</em></p>\n<p><strong>To continue, you must first activate the RNS-850’s hidden menu (Green Menu).</strong></p>\n<p><em>To activate the hidden MMI menu (Green Menu), see article: <a href=\"https://www.vag-coding.fr/vw/touareg-7p/touareg-7p-activer-menu-cache-rns-850/\" rel=\"noopener\" target=\"_blank\">RNS 850 – Activate Hidden Menu</a></em></p>\n<p>Press <strong>CAR + SETUP</strong> for 6 sec to bring up the hidden menu.</p>\n<p>car &gt; carmenuoperation</p>\n<p>Set value 5</p>\n<p>car &gt; cardevicelist</p>\n<p>Tick Auxiliary heating</p>\n<p><strong>Restart the RNS-850</strong></p>\n<p>Simultaneously press PHONE + CLIMATE + Central Button Wheel + NAV + TRAFFIC</p>","touareg-7p-adjust-led-intensity-when-lights-are-on":"<p><strong>Purpose</strong>: Allows you to adjust the brightness of the LEDs (DRL) when the headlights are on.</p>\n<p><em>By default, the LED brightness is set to 9% of maximum power when the lights are on</em>.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong>.”</p>\n<p><strong>4</strong> – Click <strong>“Security Access – 16</strong>,” then enter the code <strong>“20113”</strong></p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10”</strong></p>\n<p><strong>6 – Select </strong><em> <strong>Channel 3</strong>: </em> <br/></p>\n<p><em>Enter a new value between 5 and 100</em><br/><em>(a value less than 5% will generate an error code and a warning on the OBD)</em></p>","touareg-7p-automatic-headlamp-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong>, Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_auswahl-steuergerate-rls-wws-bord-c6f10e6e.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","touareg-7p-automatic-headlamp-activation-in-the-rain":"<p><strong>Purpose: </strong>to automatically turn on the lights when it’s raining and the wipers have been triggered.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong>, Bit <strong>1</strong>: Check “Rain Light Function Active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_auswahl-steuergerate-rls-wws-bord-c6f10e6e.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_bordnetz_rls_autobahnlicht_regenl-c0c525c9.webp\"/></figure>","touareg-7p-automatically-folding-mirrors":"<p><strong>Purpose:</strong> Automatically folds mirrors when vehicle is locked, with menu added on RNS 850.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>52 – Passenger Door</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>04</strong>: </em><br/><em>Bit <strong>6</strong>: Tick “Comfort Mirror Folding active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4F0-959-793-R_Module52_Byte4-921dde8a.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>42 – Driver’s door</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>04</strong>: </em><br/><em>Bit <strong>6</strong>: Tick “Comfort Mirror Folding active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4F0-959-793-R_Module52_Byte4-921dde8a.webp\"/></figure>\n<p><strong>Line 3:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong> then click on “<strong>46 – Central Conv.</strong></p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Choose <em>Byte<strong> 07 </strong>: </em><br/><em>Bit <strong>7</strong>: Check “Folding Mirrors installed”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4H0-907-064-CN_Module46_Byte7-eea19d21.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6383-e291dd1c.webp\"/></figure>","touareg-7p-corner-lights-activation":"<p><strong>Purpose</strong>: to switch on the fog lamp on the side where the steering wheel is turned.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Choose <em>Byte <strong>0</strong>: <br/>Bit<strong> 1</strong>: This is a hidden bit, replace the 0 with a 1 in Binary</em><br/><em>Bit <strong>2</strong>: This is a hidden bit, replace the 0 with a 1 in Binary</em></p>\n<p>Then <em>Byte <strong>4</strong>: <br/>Bit <strong>0</strong>: Check “Cornering Light via Fog Lights (depending on Sterring Angle)”.</em></p>","touareg-7p-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select Byte <strong>0</strong>:</p>\n<p>Bit <strong>2-4</strong>: select <strong>“Seat Belt Warning inactive”</strong> from the drop-down list.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","touareg-7p-disabling-start-stop":"<p><strong>Purpose:</strong> To configure Start and Stop operation. <br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong><br/></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20113</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”<strong>.<br/></strong></p>\n<p><strong>6 –</strong> Choose<strong><em> </em>Channel 34</strong></p>\n<p><em>Enter new value according to desired options</em><br/><em>–<strong>4</strong> Start&amp;Stop disabled by default</em><br/><em><strong>+32</strong> Start&amp;Stop status stored before ignition switch-off</em><br/><em><strong>+64</strong> Reverse button light (on when Start&amp;Stop enabled)</em></p>","touareg-7p-electric-tailgate-closure-with-button":"<p><strong>Purpose </strong>: to close the electric tailgate using the button on the driver’s door.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>6D – Elect. safe </strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“12345</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Activation using rear lid remote unlocking switch-Tap function for closing”</strong> from the drop-down list.</p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7N0-959-107_Module6D_Adaptation_Remote_unlocking_s-5c034a61.webp\"/></figure>","touareg-7p-electric-tailgate-closure-with-remote-control":"<p><strong>Purpose: </strong>to close the electric tailgate with the remote control.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong>6D – Elect. safe </strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“12345</strong>“.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Activation using rear lid opening button in remote key-Tap fonction for closing”</strong> from the drop-down list . </p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7N0-959-107_Module6D_Adaptation_Remote_key-Tap_fun-1faa5c43.webp\"/></figure>","touareg-7p-enable-bluetooth-streaming-audio-a2dp-rns-850":"<p><strong>Purpose</strong>: Enables Bluetooth audio streaming on the RNS 850, so you can listen to music from your A2DP-compatible audio player.  </p>\n<p><em>ATTENTION: You must have activated the Hidden Menu (<a href=\"#/vw/touareg-7p/touareg-7p-activate-hidden-menu-rns-850\">Activate RNS 850 hidden menu</a>)</em> and enabled Bluetooth (either by default or via the “RNS 850 Bluetooth activation” tutorial).  </p>\n<p>Press CAR + MENU (for 6s)  </p>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AMI BT [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ami_bt-8fa46d9c.webp\"/></figure>\n<p>bluetooth -&gt; Check <strong>A2DP Activation</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ad2p-90e760bc.webp\"/></figure>\n<p>Restart RNS 850</p>\n<p>Simultaneously press PHONE (1) + CLIMATE (2) + Central knob (3) + NAV (4) + TRAFFIC (5)<em>.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNS850BT-3f0fe368.webp\"/></figure>","touareg-7p-enable-rns-850-cd-dvd-ripping":"<p><strong>Purpose</strong>: Activates CD/DVD extraction in the DVD drive. Allows you to import / copy all CD/DVD / SD card content to the RNS 850’s jukebox (hard disk).   </p>\n<p><strong>To continue, you must first have activated the hidden RNS menu (Green Menu).</strong></p>\n<p><em><em>To activate the RNS hidden menu (Green Menu) :</em> <a href=\"#/vw/touareg-7p/touareg-7p-activate-hidden-menu-rns-850\">Activate RNS 850 hidden menu</a></em></p>\n<p>Press <strong>CAR + MENU</strong> for 6 sec to bring up the hidden menu.</p>\n<p>diagnose -&gt; settings -&gt; import_multimedia -&gt; Tick <strong>Ripping</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi3g_plus_hidden_menu_cd-ripping-cbf13d3b.webp\"/></figure>\n<p><strong>Restart RNS</strong></p>\n<p><em>Simultaneously press the “PHONE”, “CLIMATE”, “NAV”, “TRAFFIC” buttons and the rotary knob.</em></p>\n<p><em>In the RNS 850, the “recording” function is now visible and active under the Extras menu, then Media.</em></p>","touareg-7p-headlamp-washer-settings":"<p><strong>Purpose:</strong> to set the delay time before the headlamp washer emerges / the duration of the headlamp washer spray / the number of activations.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1 (Headlamp washer activation time) :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 25</strong>: </em> </p>\n<p><em>Set value to </em><strong><em>“</em>8000”</strong> or value of your choice (default: 2000 ms)  </p>\n<p><strong>Line 2 (Headlamp washer spray duration) :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 06</strong>: </em> </p>\n<p><em>adjust value accordingly (in ms)</em></p>\n<p><strong>Line 3 <strong>(Number of activations before headlamp washer) :</strong></strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 26</strong>: </em><br/><em>adjust the value for the number of times the headlamp washer must be switched on manually before activation.</em></p>","touareg-7p-locking-unlocking-confirmation-beeps":"<p><strong>Purpose</strong>: Enables vehicle lock/unlock confirmation with beeps.  </p>\n<p><strong>The vehicle must be equipped with the factory-installed alarm</strong>.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>1</strong>: </em> </p>\n<p><em>Bit <strong>2</strong>: Check “Anti-Theft System: Horn Confirmation Active”</em></p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <em><strong>Canal 63</strong>: </em> </p>\n<p><em>Add <strong>04</strong> to the value  </em></p>","touareg-7p-lower-passenger-mirror-when-reversing":"<p><strong>Purpose:</strong> automatically lowers the passenger mirror when reversing.  </p>\n<p>The mirror adjustment knob must be in position<strong>“R”</strong> for the passenger mirror to lower automatically.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“4</strong>”<br/>Then check Bit<strong>“2</strong>”:<strong>“Reserve Gear Mirror Dipping active</strong>”<br/>and Bit<strong>“3</strong>”:<strong>“Position Memory for Reserve Gear Mirror Dipping active</strong>”.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-Abaisser-le-retroviseur-passager-lors-de-la-9710a97c.webp\"/></figure>","touareg-7p-maintain-led-intensity-with-turn-signals":"<p><strong>Purpose</strong>: Maintains the brightness of the LEDs (DRLs) when the turn signals are on.</p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/>3 – Click on ” <strong>Select”, then click on ” Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>“.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong> “Long Coding Helper”</strong>.</p>\n<p><strong>5</strong> – Select <em>Byte <strong>3 : </strong> </em> </p>\n<p><em>Bit<strong> 7</strong>: Uncheck “</em><strong><em>Daytime Running Lights inactive with Turn Signal (” Winking “) active</em></strong><em>”</em></p>","touareg-7p-needle-check":"<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. (Needle Sweep)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Gauge Test/Needle Sweep active</strong>”.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>","touareg-7p-oil-temperature-on-odb":"<p><strong>Purpose:</strong> to display oil temperature on the ODB (on-board computer). (For 2010/early 2011 models)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose Channel <strong>07</strong>:<strong>“Konfiguration des Fahrerinformationssysyems-Öltemperatur</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.<br/><br/></p>","touareg-7p-rear-daytime-running-lights-drl":"<p><strong>Purpose</strong>: Enables the use of the taillights as daytime running lights (Scandinavian DRL).</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “ <strong>Coding – 07.”</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 2: </strong></p>\n<p>Bit <strong>7</strong>: Check <em>“<strong>Daytime running lights via Tails Lights active</strong>“</em> </p>","touareg-7p-rns-850-bluetooth-activation":"<p><strong>Purpose</strong>: to activate Bluetooth on vehicles equipped with the RNS-850.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>To continue, you must first activate the RNS 850’s hidden menu (Green Menu).</strong></p>\n<p><em>To activate the hidden MMI menu (Green Menu) : <a href=\"#/vw/touareg-7p/touareg-7p-activate-hidden-menu-rns-850\">Activate RNS 850 Hidden Menu</a></em></p>\n<p><strong>Step 1: Activate Bluetooth in the hidden menu</strong></p>\n<p>Press <strong>CAR + MENU</strong> for 6 sec to bring up the hidden menu.</p>\n<p>diagnostics  &gt;  settings  &gt;  tel_settings -&gt;  Select <strong>“HFP activation”</strong><br/>diagnose   &gt;  settings  &gt;  tel_settings -&gt;  Select <strong>“BT activation”</strong><br/>diagnostics   &gt;  settings  &gt;  tel_settings -&gt;  Select  <strong>“BT defaut visibility” to [auto] 1/3</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_tel_settings-af0d9718.webp\"/></figure>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AMI BT [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ami_bt-8fa46d9c.webp\"/></figure>\n<p><strong>Step 2: Restart</strong> <strong>RNS 850</strong></p>\n<p>Simultaneously press PHONE (1) + CLIMATE (2) + Central knob (3) + NAV (4) + TRAFFIC (5)</p>\n<p><br/><strong>Step 3: Bluetooth activation with VCDS</strong><br/><br/> 3 – Click on ” <strong>Select”</strong> and then click on ” “.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 17</strong> </em>then set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Module_5F_Adaptation_Channel17-d3fc3a63.webp\"/></figure>","touareg-7p-tear-wiping":"<p><strong>Purpose:</strong> to activate the windshield wipers once more after using the windshield washer, in order to remove any remaining water from the windshield.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on <strong>“Coding – 07”</strong> and<em>“x – 8K1 955 119 – WWS</em> (in the drop-down list)” then <strong>“Long Coding Helper”.</strong></p>\n<p><strong>5</strong> – Select byte <strong>1</strong>: <br/>Bit<strong> 3</strong>, Check <strong>“Tear Wiping Active”</strong>.</p>"};
